/* Native media delivery/lease owner.
 *
 * This is intentionally between MediaLibrary's direct-representation plan and
 * a carrier.  It owns explicit, bounded delivery leases only.  It does not
 * own a media object, use a CMS music_right as a licence grant, start a
 * transcoder, emit HLS/DASH bytes, establish MOQT, or record watch proof. */
#define _POSIX_C_SOURCE 200809L
#include <sqlite3.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

static const char *arg(int ac,char **av,const char *name){for(int i=2;i+1<ac;i++)if(!strcmp(av[i],name))return av[i+1];return NULL;}
static int tok(const char*s){if(!s||!*s||strlen(s)>511)return 0;for(;*s;s++)if(!((*s>='a'&&*s<='z')||(*s>='A'&&*s<='Z')||(*s>='0'&&*s<='9')||*s==':'||*s=='-'||*s=='_'||*s=='.'||*s=='/'))return 0;return 1;}
static int protocol(const char*s){return s&&(!strcmp(s,"hls")||!strcmp(s,"dash")||!strcmp(s,"moqt"));}
static void js(const char*s){const unsigned char*p=(const unsigned char*)(s?s:"");putchar('"');for(;*p;p++){if(*p=='"'||*p=='\\'){putchar('\\');putchar(*p);}else if(*p=='\n')fputs("\\n",stdout);else if(*p<32)printf("\\u%04x",*p);else putchar(*p);}putchar('"');}
static int sql(sqlite3*d,const char*s){char*e=0;int ok=sqlite3_exec(d,s,0,0,&e)==SQLITE_OK;if(!ok){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);}return ok;}
static int open_db(const char*p,sqlite3**d){if(sqlite3_open(p,d)!=SQLITE_OK)return 0;return sql(*d,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS media_delivery_right(right_id TEXT PRIMARY KEY,library_id TEXT NOT NULL,subject_ref TEXT NOT NULL,representation_id TEXT NOT NULL,actor_subject TEXT NOT NULL,protocol TEXT NOT NULL CHECK(protocol IN('hls','dash','moqt')),starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('active','revoked')),evidence_ref TEXT NOT NULL,granted_by TEXT NOT NULL,created_at INTEGER NOT NULL);CREATE INDEX IF NOT EXISTS media_delivery_right_lookup ON media_delivery_right(library_id,subject_ref,representation_id,actor_subject,protocol,state,starts_at,ends_at);CREATE TABLE IF NOT EXISTS media_transport_lease(lease_id TEXT PRIMARY KEY,right_id TEXT NOT NULL,library_id TEXT NOT NULL,subject_ref TEXT NOT NULL,representation_id TEXT NOT NULL,actor_subject TEXT NOT NULL,protocol TEXT NOT NULL,issued_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('active','revoked','expired')),created_at INTEGER NOT NULL);");}
static int json_str(const char*j,const char*k,char*out,size_t cap){char n[96];const char*p;size_t z=0;if(!j||!k||!out||cap<2||snprintf(n,sizeof(n),"\"%s\"",k)>=(int)sizeof(n))return 0;p=strstr(j,n);if(!p||(p=strchr(p+strlen(n),':'))==0)return 0;while(*++p==' '||*p=='\n'||*p=='\r'||*p=='\t'){}if(*p++!='\"')return 0;while(*p&&*p!='\"'){if(*p=='\\'&&!*++p)return 0;if((unsigned char)*p<32||z+1>=cap)return 0;out[z++]=*p++;}if(*p!='\"'||!z)return 0;out[z]=0;return 1;}
static int json_state(const char*j,const char*state){char got[80];return json_str(j,"state",got,sizeof(got))&&!strcmp(got,state);}
static int token_stdin(char*out,size_t cap){size_t n=0;int c;if(!out||cap<2)return 0;while((c=fgetc(stdin))!=EOF){if(c=='\n'||c=='\r')break;if(c<0x21||c>0x7e||n+1>=cap)return 0;out[n++]=(char)c;}out[n]=0;return n>0;}
/* A MOQT lease reference is carried as an authorization token.  It therefore
 * cannot be a timestamp/pid guess: the lease owner mints an opaque random
 * capability reference and records its scope locally. */
static int lease_id(char*out,size_t cap){unsigned char raw[16];static const char hex[]="0123456789abcdef";int fd;if(!out||cap<39||(fd=open("/dev/urandom",O_RDONLY))<0)return 0;if(read(fd,raw,sizeof(raw))!=(ssize_t)sizeof(raw)){close(fd);return 0;}close(fd);memcpy(out,"lease:",6);for(size_t i=0;i<sizeof(raw);i++){out[6+i*2]=hex[raw[i]>>4];out[7+i*2]=hex[raw[i]&15];}out[38]=0;return 1;}
static int child_json(char *const av[],const char*input,char*out,size_t cap){int in[2],fd[2],status=0;pid_t p;size_t got=0;ssize_t n;if(pipe(in)||pipe(fd))return 0;p=fork();if(p<0){close(in[0]);close(in[1]);close(fd[0]);close(fd[1]);return 0;}if(!p){close(in[1]);close(fd[0]);if(dup2(in[0],0)<0||dup2(fd[1],1)<0)_exit(127);close(in[0]);close(fd[1]);execvp(av[0],av);_exit(127);}close(in[0]);close(fd[1]);if(write(in[1],input,strlen(input))!=(ssize_t)strlen(input)||write(in[1],"\n",1)!=1){close(in[1]);close(fd[0]);waitpid(p,&status,0);return 0;}close(in[1]);while(got+1<cap&&(n=read(fd[0],out+got,cap-1-got))>0)got+=(size_t)n;close(fd[0]);out[got]=0;return waitpid(p,&status,0)>=0&&WIFEXITED(status)&&WEXITSTATUS(status)==0&&got>0;}
static int actor_closure(const char*auth,const char*adb,const char*bearer,char*actor,size_t cap){char buf[2048];char*const av[]={(char*)auth,"--db",(char*)adb,"actor-closure-stdin",0};return child_json(av,bearer,buf,sizeof(buf))&&json_str(buf,"actor_subject",actor,cap)&&tok(actor);}
typedef struct {char actor[256],program[256],subject[256],representation[128],codec[80];} DirectPlan;
static int direct_plan(const char*media,const char*mdb,const char*cms,const char*adb,const char*bearer,const char*lib,const char*subject,const char*cap,DirectPlan*p){char out[8192];char*const av[]={(char*)media,"authenticated-playback-plan","--db",(char*)mdb,"--cms-db",(char*)cms,"--auth-db",(char*)adb,"--auth-token-stdin","--library",(char*)lib,"--subject",(char*)subject,"--capabilities",(char*)cap,0};return child_json(av,bearer,out,sizeof(out))&&json_state(out,"DIRECT_PLAYABLE")&&json_str(out,"actor_subject",p->actor,sizeof(p->actor))&&json_str(out,"media_program_ref",p->program,sizeof(p->program))&&json_str(out,"subject_ref",p->subject,sizeof(p->subject))&&json_str(out,"representation_id",p->representation,sizeof(p->representation))&&json_str(out,"codec",p->codec,sizeof(p->codec));}
static int cmd_right(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--id"),*lib=arg(ac,av,"--library"),*sub=arg(ac,av,"--subject"),*rep=arg(ac,av,"--representation"),*actor=arg(ac,av,"--actor"),*p=arg(ac,av,"--protocol"),*start=arg(ac,av,"--starts-at"),*end=arg(ac,av,"--ends-at"),*e=arg(ac,av,"--evidence"),*by=arg(ac,av,"--by");sqlite3_stmt*s=0;long long a=start?strtoll(start,0,10):0,b=end?strtoll(end,0,10):0;if(!tok(id)||!tok(lib)||!tok(sub)||!tok(rep)||!tok(actor)||!protocol(p)||!tok(e)||!tok(by)||a<0||b<=a)return 0;if(sqlite3_prepare_v2(d,"INSERT OR REPLACE INTO media_delivery_right VALUES(?1,?2,?3,?4,?5,?6,?7,?8,'active',?9,?10,?11)",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,0);sqlite3_bind_text(s,2,lib,-1,0);sqlite3_bind_text(s,3,sub,-1,0);sqlite3_bind_text(s,4,rep,-1,0);sqlite3_bind_text(s,5,actor,-1,0);sqlite3_bind_text(s,6,p,-1,0);sqlite3_bind_int64(s,7,a);sqlite3_bind_int64(s,8,b);sqlite3_bind_text(s,9,e,-1,0);sqlite3_bind_text(s,10,by,-1,0);sqlite3_bind_int64(s,11,time(0));int ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-media-delivery-right.v1\",\"right_id\":",stdout);js(id);fputs(",\"state\":\"active\",\"truth\":\"explicit_delivery_eligibility_not_media_ownership_or_delivery\"}\n",stdout);}return ok;}
/* A revocation is an owner-state transition, never a client-side token hint.
 * Retire all still-active derived leases atomically; each carrier must still
 * requery lease-status when a new request arrives. */
static int cmd_right_revoke(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--id"),*by=arg(ac,av,"--by");sqlite3_stmt*s=0;int ok=0;if(!tok(id)||!tok(by)||!sql(d,"BEGIN IMMEDIATE"))return 0;if(sqlite3_prepare_v2(d,"UPDATE media_delivery_right SET state='revoked' WHERE right_id=?1 AND state='active'",-1,&s,0)==SQLITE_OK){sqlite3_bind_text(s,1,id,-1,0);ok=sqlite3_step(s)==SQLITE_DONE&&sqlite3_changes(d)==1;sqlite3_finalize(s);}if(ok&&sqlite3_prepare_v2(d,"UPDATE media_transport_lease SET state='revoked' WHERE right_id=?1 AND state='active'",-1,&s,0)==SQLITE_OK){sqlite3_bind_text(s,1,id,-1,0);ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);}if(!sql(d,ok?"COMMIT":"ROLLBACK"))ok=0;if(ok){fputs("{\"schema\":\"bonfyre-media-delivery-right-revocation.v1\",\"right_id\":",stdout);js(id);fputs(",\"state\":\"REVOKED\",\"truth\":\"revoked_right_and_active_derived_leases_not_delivery_or_watch_proof\"}\n",stdout);}return ok;}
static int cmd_lease_revoke(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--lease"),*by=arg(ac,av,"--by");sqlite3_stmt*s=0;int ok=0;if(!tok(id)||!tok(by)||sqlite3_prepare_v2(d,"UPDATE media_transport_lease SET state='revoked' WHERE lease_id=?1 AND state='active'",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,0);ok=sqlite3_step(s)==SQLITE_DONE&&sqlite3_changes(d)==1;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-media-transport-lease-revocation.v1\",\"lease_id\":",stdout);js(id);fputs(",\"state\":\"REVOKED\",\"truth\":\"revoked_transport_eligibility_not_delivery_or_watch_proof\"}\n",stdout);}return ok;}
static int right_for(sqlite3*d,const char*lib,const char*sub,const char*rep,const char*actor,const char*p,long long now,char*id,size_t cap,long long*ends){sqlite3_stmt*s=0;int ok=0;if(sqlite3_prepare_v2(d,"SELECT right_id,ends_at FROM media_delivery_right WHERE library_id=?1 AND subject_ref=?2 AND representation_id=?3 AND actor_subject=?4 AND protocol=?5 AND state='active' AND starts_at<=?6 AND ends_at>?6 ORDER BY ends_at LIMIT 1",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,lib,-1,0);sqlite3_bind_text(s,2,sub,-1,0);sqlite3_bind_text(s,3,rep,-1,0);sqlite3_bind_text(s,4,actor,-1,0);sqlite3_bind_text(s,5,p,-1,0);sqlite3_bind_int64(s,6,now);if(sqlite3_step(s)==SQLITE_ROW){snprintf(id,cap,"%s",sqlite3_column_text(s,0)?(const char*)sqlite3_column_text(s,0):"");*ends=sqlite3_column_int64(s,1);ok=tok(id);}sqlite3_finalize(s);return ok;}
static int cmd_lease(sqlite3*d,int ac,char**av){const char*mdb=arg(ac,av,"--media-library-db"),*cms=arg(ac,av,"--cms-db"),*adb=arg(ac,av,"--auth-db"),*lib=arg(ac,av,"--library"),*sub=arg(ac,av,"--subject"),*cap=arg(ac,av,"--capabilities"),*p=arg(ac,av,"--protocol"),*ttl=arg(ac,av,"--ttl-seconds"),*media=getenv("BONFYRE_MEDIA_LIBRARY_BIN"),*auth=getenv("BONFYRE_AUTH_BIN");char bearer[192],actor[256],right[128],lid[256];DirectPlan plan={0};long long now=time(0),expires,right_end;sqlite3_stmt*s=0;int requested=ttl?atoi(ttl):300;if(!media||!*media)media="bonfyre-media-library";if(!auth||!*auth)auth="bonfyre-auth";if(!mdb||!cms||!adb||!tok(lib)||!tok(sub)||!cap||!protocol(p)||requested<1||requested>3600||!token_stdin(bearer,sizeof(bearer)))return 0;if(!actor_closure(auth,adb,bearer,actor,sizeof(actor))||!direct_plan(media,mdb,cms,adb,bearer,lib,sub,cap,&plan)||strcmp(actor,plan.actor)||strcmp(sub,plan.subject))return 0;if(!right_for(d,lib,sub,plan.representation,actor,p,now,right,sizeof(right),&right_end)){fputs("{\"schema\":\"bonfyre-media-transport-lease.v1\",\"state\":\"REFUSED_RIGHT_REQUIRED\",\"truth\":\"no_delivery_or_transport_session\"}\n",stdout);return 0;}expires=now+requested;if(expires>right_end)expires=right_end;if(!lease_id(lid,sizeof(lid)))return 0;if(sqlite3_prepare_v2(d,"INSERT INTO media_transport_lease VALUES(?1,?2,?3,?4,?5,?6,?7,?8,?9,'active',?8)",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,lid,-1,0);sqlite3_bind_text(s,2,right,-1,0);sqlite3_bind_text(s,3,lib,-1,0);sqlite3_bind_text(s,4,sub,-1,0);sqlite3_bind_text(s,5,plan.representation,-1,0);sqlite3_bind_text(s,6,actor,-1,0);sqlite3_bind_text(s,7,p,-1,0);sqlite3_bind_int64(s,8,now);sqlite3_bind_int64(s,9,expires);int ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-media-transport-lease.v1\",\"lease_id\":",stdout);js(lid);fputs(",\"right_id\":",stdout);js(right);fputs(",\"actor_subject\":",stdout);js(actor);fputs(",\"library_id\":",stdout);js(lib);fputs(",\"subject_ref\":",stdout);js(sub);fputs(",\"representation_id\":",stdout);js(plan.representation);fputs(",\"protocol\":",stdout);js(p);printf(",\"expires_at\":%lld,\"state\":\"LEASED_NOT_DELIVERED\",\"truth\":\"lease_only_no_bytes_transcode_session_or_watch_proof\"}\n",expires);}return ok;}
static int cmd_inspect(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--lease");sqlite3_stmt*s=0;long long now=time(0),exp=0;const char*state=0;if(!tok(id)||sqlite3_prepare_v2(d,"SELECT state,expires_at,protocol,representation_id FROM media_transport_lease WHERE lease_id=?1",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,0);if(sqlite3_step(s)!=SQLITE_ROW){sqlite3_finalize(s);return 0;}state=(const char*)sqlite3_column_text(s,0);exp=sqlite3_column_int64(s,1);const char*p=(const char*)sqlite3_column_text(s,2),*rep=(const char*)sqlite3_column_text(s,3);fputs("{\"schema\":\"bonfyre-media-transport-lease-status.v1\",\"lease_id\":",stdout);js(id);fputs(",\"protocol\":",stdout);js(p);fputs(",\"representation_id\":",stdout);js(rep);fputs(",\"state\":",stdout);js(exp<=now?"EXPIRED":(state?state:"unknown"));printf(",\"expires_at\":%lld,\"truth\":\"lease_status_not_delivery_or_watch_proof\"}\n",exp);sqlite3_finalize(s);return 1;}
static void use(void){fputs("bonfyre-media-delivery right-put --db FILE --id ID --library ID --subject SUBJECT --representation ID --actor SUBJECT --protocol hls|dash|moqt --starts-at EPOCH --ends-at EPOCH --evidence REF --by SUBJECT\n bonfyre-media-delivery right-revoke --db FILE --id ID --by SUBJECT\n bonfyre-media-delivery authenticated-lease --db FILE --media-library-db FILE --cms-db FILE --auth-db FILE --library ID --subject SUBJECT --capabilities JSON --protocol hls|dash|moqt [--ttl-seconds N] < bearer-token\n bonfyre-media-delivery lease-revoke --db FILE --lease ID --by SUBJECT\n bonfyre-media-delivery lease-status --db FILE --lease ID\n",stderr);}
int main(int ac,char**av){const char*p=arg(ac,av,"--db");sqlite3*d=0;int ok=0;if(ac<2||!p){use();return 2;}if(!open_db(p,&d))return 1;if(!strcmp(av[1],"right-put"))ok=cmd_right(d,ac,av);else if(!strcmp(av[1],"right-revoke"))ok=cmd_right_revoke(d,ac,av);else if(!strcmp(av[1],"authenticated-lease"))ok=cmd_lease(d,ac,av);else if(!strcmp(av[1],"lease-revoke"))ok=cmd_lease_revoke(d,ac,av);else if(!strcmp(av[1],"lease-status"))ok=cmd_inspect(d,ac,av);else{use();sqlite3_close(d);return 2;}sqlite3_close(d);return ok?0:1;}
